{"fw_ld4_quick_c_0005","any",3,"reg=civilian,family,worker,rescue",{1,"Rock, paper, scissors for the watch",2,"Best of three",3,"I always lose",1,"Then lose gracefully",3,"...scissors, damn it"}},
{"fw_ld4_quick_c_0006","any",3,"reg=civilian,family,worker,rescue",{1,"Look who found a harmonica",2,"I can play 'Mary Had a Little Lamb'",3,"Please don't",2,"Too late, Mary had a little...",1,"Stop, stop, we'll pay you not to play"}},
{"fw_ld4_quick_c_0007","any",3,"reg=civilian,family,worker,rescue",{1,"What do we do with the cat?",2,"Keep it",3,"It scratched me",1,"It likes you",3,"It likes my blood"}},
{"fw_ld4_quick_c_0008","any",3,"reg=civilian,family,worker,rescue",{1,"I'm cold",2,"Me too",3,"Me three",1,"Then let's all squeeze together",2,"This is awkward",3,"Awkward is warm"}},
{"fw_ld4_quick_c_0009","any",3,"reg=civilian,family,worker,rescue",{1,"Does anyone know how to cook rabbit?",2,"I know how to skin it",3,"I know how to burn it",1,"Great, so one of you cooks, and one cleans up"}},
{"fw_ld4_quick_c_0010","any",3,"reg=civilian,family,worker,rescue",{1,"I found a deck of cards",2,"Let's play",3,"What game?",1,"Go fish",2,"Go fish is for children",3,"We're all children now"}},
{"fw_ld4_quick_c_0011","any",3,"reg=civilian,family,worker,rescue",{1,"Where's the baby?",2,"With Maggie",3,"Where's Maggie?",1,"With the baby",2,"That's a circle",3,"At least they're together"}},
{"fw_ld4_quick_c_0012","any",3,"reg=civilian,family,worker,rescue",{1,"Whose boots are these?",2,"Mine",3,"Mine",1,"They can't both be yours",2,"They're a pair, genius, one's mine, one's his",3,"We share a pair, it's called poverty"}},
{"fw_ld4_quick_c_0013","any",3,"reg=civilian,family,worker,rescue|world=wind",{1,"Quiet, listen",2,"To what?",3,"The wind",1,"It sounds like whispering",2,"It's just wind",3,"Wind doesn't say 'help'"}},
{"fw_ld4_quick_c_0014","any",3,"reg=civilian,family,worker,rescue",{1,"Anybody else miss Sundays?",2,"I miss Sunday football",3,"I miss Sunday dinner",1,"I miss Sunday sleeping in",2,"Sunday was the best day",3,"Every day was a Sunday if you had the right attitude"}},
{"fw_ld4_quick_c_0015","any",3,"reg=civilian,family,worker,rescue",{1,"Something smells awful",2,"Not me",3,"Not me",1,"It's the beans, I can tell",2,"We've been eating nothing but beans",3,"Then it's all of us"}},
{"fw_ld4_quick_c_0016","any",3,"reg=civilian,family,worker,rescue",{1,"What's the plan for tomorrow?",2,"Walk",3,"Where?",1,"North",2,"Why north?",3,"Because south is worse"}},
{"fw_ld4_quick_c_0017","any",3,"reg=civilian,family,worker,rescue|hour=20,5",{1,"Who wants first watch?",2,"I'll take it",3,"Wake me at midnight",1,"Wake me at two",2,"I'll wake everyone at once, that's easier"}},
{"fw_ld4_quick_c_0018","any",3,"reg=civilian,family,worker,rescue",{1,"Is it me, or is the can bigger today?",2,"It's the same can",3,"It looks bigger",1,"It looks hungry",2,"We look hungry"}},
{"fw_ld4_quick_c_0019","any",3,"reg=civilian,family,worker,rescue",{1,"I made a necklace",2,"From what?",3,"A bottle cap and string",1,"It's actually pretty",2,"Make me one",3,"Make me two"}},
{"fw_ld4_quick_c_0020","any",3,"reg=civilian,family,worker,rescue",{1,"I'm gonna write a book about this",2,"Who'd read it?",3,"Nobody",1,"Then I'll write for myself",2,"Title?",1,"'The Long Walk Home', and it doesn't have an ending yet"}},
{"fw_ld4_quick_c_0021","any",3,"reg=civilian,family,worker,rescue|tmp=seasoned",{1,"Can I tell you something dumb?",2,"Always",3,"Please do",1,"I'm not scared of the dead anymore",2,"That's not dumb",3,"That's terrifying",1,"Right, because I should be scared"}},
{"fw_ld4_quick_c_0022","any",3,"reg=civilian,family,worker,rescue|tmp=seasoned|world=road",{1,"First rule of the road",2,"Don't die",3,"Second rule?",2,"Don't be the reason somebody else dies",1,"Third rule?",3,"Share the food"}},
{"fw_ld4_quick_c_0023","any",3,"reg=civilian,family,worker,rescue|tmp=fresh",{1,"What if we get caught?",2,"By who?",3,"By anyone",1,"Then we'll talk",2,"And if talking fails?",3,"Run"}},
{"fw_ld4_quick_c_0024","any",3,"reg=civilian,family,worker,rescue|tmp=fresh",{1,"Shhh, they're sleeping",2,"Who?",1,"The baby, and Mr. Henderson",3,"They're snoring in harmony",2,"It's almost beautiful"}},
{"fw_ld4_quick_c_0025","any",3,"reg=law,swat",{1,"Briefing in five",2,"What's on the agenda?",3,"Supplies, patrols, morale",1,"And donuts?",2,"No donuts",3,"Then what's the point?"}},
{"fw_ld4_quick_c_0026","any",3,"reg=law,swat",{1,"Who's got the radio?",2,"I do",3,"Does it work?",2,"It makes noise, which counts",1,"Noise isn't communication"}},
{"fw_ld4_quick_c_0027","any",3,"reg=law,swat",{1,"Everyone alright?",2,"Yeah",3,"Yeah",1,"Sound off properly, Reyes",3,"Present, Sergeant, and slightly annoyed"}},
{"fw_ld4_quick_c_0028","any",3,"reg=military,elite",{1,"Open order, spread out",2,"Yes sir",3,"Yes sir",1,"Smith, you're too close to Jones",3,"He smells better, sir"}},
{"fw_ld4_quick_c_0029","any",3,"reg=military,elite",{1,"Who's got the map?",2,"I thought you had it",3,"I thought Dave had it",1,"Dave's dead",2,"...then Dave has the map"}},
{"fw_ld4_quick_c_0030","any",3,"reg=military,elite",{1,"Anybody got a smoke?",2,"No",3,"No",1,"Great, a squad of non-smokers, we're doomed"}},
{"fw_ld4_quick_c_0031","any",3,"reg=military,elite",{1,"Roll call",2,"Present",3,"Present",1,"Reyes?",2,"He stepped out, sir",3,"To pee, sir, he'll be back"}},
{"fw_ld4_quick_c_0032","any",3,"reg=outlaw,raider,gang,club,crime,prison",{1,"Who stole my bottle?",2,"Not me",3,"Not me",1,"It was on the shelf",2,"Maybe it evaporated",3,"Maybe you drank it"}},
{"fw_ld4_quick_c_0033","any",3,"reg=outlaw,raider,gang,club,crime,prison",{1,"We split three ways",2,"Why three?",3,"There's three of us",1,"There's four",2,"Four? Who's the fourth?",3,"...the dog"}},
{"fw_ld4_quick_c_0034","any",3,"reg=outlaw,raider,gang,club,crime,prison",{1,"Cut the cards",2,"Why?",3,"Because I trust nobody",1,"Smart",2,"Just kidding, I trust you, I just want to win"}},
{"fw_ld4_quick_c_0035","any",3,"reg=outlaw,raider,gang,club,crime,prison|hour=4,9",{1,"Boss wants the loot by sunrise",2,"What loot?",3,"Whatever we can steal",1,"That's vague",2,"He likes vague, it keeps us guessing"}},
{"fw_ld4_quick_c_0036","any",3,"reg=family",{1,"Come to the table",2,"Is it supper?",3,"Is it good?",1,"It's beans",2,"Aw",3,"With love, Mama, with love"}},
