{"fw_ld4_quick_d_0001","any",2,"reg=civilian,family,worker,rescue",{1,"How do I look?",2,"Like you've been dragged behind a horse",1,"Thanks",2,"A cute horse, though"}},
{"fw_ld4_quick_d_0002","any",2,"reg=civilian,family,worker,rescue",{1,"What was that noise?",2,"My stomach?",1,"No, a noise",2,"It was my stomach, the noise was my stomach"}},
{"fw_ld4_quick_d_0003","any",2,"reg=civilian,family,worker,rescue",{1,"I got a splinter",2,"Show me",1,"It's tiny",2,"It's huge, hold still, this will hurt me more than you"}},
{"fw_ld4_quick_d_0004","any",2,"reg=civilian,family,worker,rescue",{1,"What time is it?",2,"Time to move",1,"That's not a time",2,"It's the only time that matters"}},
