{"fw_ld4_quick_d_0006","any",2,"reg=civilian,family,worker,rescue",{1,"I like your laugh",2,"It's an ugly laugh",1,"It's the best sound I've heard all week",2,"You're welcome, I guess"}},
{"fw_ld4_quick_d_0007","any",2,"reg=civilian,family,worker,rescue",{1,"Did you see where she went?",2,"Who?",1,"The lady with the red hat",2,"She went that way, you couldn't miss that hat"}},
{"fw_ld4_quick_d_0008","any",2,"reg=civilian,family,worker,rescue",{1,"I think I'm getting a cold",2,"Don't",1,"It's too late",2,"Then stay over there, and wash your hands"}},
