{"fw_ld4_quick_d_0014","any",2,"reg=civilian,family,worker,rescue",{1,"Whatever happens, thank you",2,"For what?",1,"For not leaving me",2,"I wouldn't dream of it"}},
{"fw_ld4_quick_d_0015","any",2,"reg=civilian,family,worker,rescue",{1,"I once stole a doll",2,"Why?",1,"For a girl who hadn't smiled in days",2,"Did you give it to her, or just keep deciding how you'd explain it?"}},
{"fw_ld4_quick_d_0016","any",2,"reg=civilian,family,worker,rescue",{1,"I'm useless without coffee",2,"You're useless with coffee",1,"That's mean",2,"It's affectionate, mostly"}},
{"fw_ld4_quick_d_0017","any",2,"reg=civilian,family,worker,rescue|hour=20,5",{1,"Do you pray?",2,"When it's dark",1,"And when it's light?",2,"I forget, then remember at dusk, God's patient"}},
{"fw_ld4_quick_d_0018","any",2,"reg=civilian,family,worker,rescue",{1,"What's your favorite color?",2,"Blue",1,"Why?",2,"Because it's the color of the sky on a good day"}},
{"fw_ld4_quick_d_0019","any",2,"reg=civilian,family,worker,rescue",{1,"I hate this place",2,"It's alive",1,"That's all you can say about it?",2,"It's the only compliment I've got"}},
{"fw_ld4_quick_d_0020","any",2,"reg=civilian,family,worker,rescue",{1,"Be careful, that's sharp",2,"I know, I know",1,"Be MORE careful",2,"Mom, I'm thirty-five"}},
{"fw_ld4_quick_d_0021","any",2,"reg=civilian,family,worker,rescue",{1,"Dance with me",2,"Here?",1,"Right here",2,"There's no music",1,"Hum"}},
