{"fw_ld4_quick_d_0025","any",2,"reg=civilian,family,worker,rescue|world=hot",{1,"You make a great cup of tea",2,"It's hot water and a pine twig",1,"It's the best twig tea I've ever had",2,"It's the only twig tea you've ever had"}},
{"fw_ld4_quick_d_0026","any",2,"reg=civilian,family,worker,rescue",{1,"Are you crying?",2,"No",1,"Your face is wet",2,"It's sweat",1,"From your eyes?",2,"Mind your business"}},
{"fw_ld4_quick_d_0027","any",2,"reg=civilian,family,worker,rescue",{1,"I'm going to find help",2,"Where?",1,"I don't know yet",2,"Then you're not going yet"}},
{"fw_ld4_quick_d_0028","any",2,"reg=civilian,family,worker,rescue",{1,"I wish I could sleep for a year",2,"And wake up when it's over?",1,"And wake up and find everything's fine",2,"I'll wake you, if it ever is"}},
{"fw_ld4_quick_d_0029","any",2,"reg=civilian,family,worker,rescue",{1,"Hey, I'm sorry about the other night",2,"Forget it",1,"I was out of line",2,"We all were, keep walking"}},
