{"fw_ld4_quick_d_0033","any",2,"reg=civilian,family,worker,rescue|tmp=fresh",{1,"Do you think we'll be okay?",2,"I think we'll be tired",1,"That's not the same",2,"It's the best I've got"}},
{"fw_ld4_quick_d_0034","any",2,"reg=civilian,family,worker,rescue|tmp=seasoned",{1,"That's the third time you've told that story",2,"It's a good story",1,"It's a great story, the third time",2,"Wait till you hear the fourth"}},
