{"fw_ld4_quick_d_0040","any",2,"reg=military,elite",{1,"Wanna know what I miss?",2,"What?",1,"Taco Tuesday",2,"Taco Tuesday was a good day"}},
{"fw_ld4_quick_d_0041","any",2,"reg=outlaw,raider,gang,club,crime,prison",{1,"How much did you steal?",2,"Enough",1,"Enough for what?",2,"Enough to keep me out of the cold"}},
