{"fw_ld4_quick_e_0010","any",2,"reg=civilian,family,worker,rescue",{1,"Is it my fault?",2,"What?",1,"Everything",2,"No",1,"Then why do I feel like it is?",2,"Because you're a decent person in an indecent world"}},
{"fw_ld4_quick_e_0011","any",2,"reg=civilian,family,worker,rescue",{1,"You think I'm weak",2,"I think you're scared",1,"Same thing",2,"It's not, scared people do brave things all the time"}},
