{"fw_ld4_quick_e_0015","any",2,"reg=civilian,family,worker,rescue",{1,"I told you not to touch it",2,"I didn't",1,"It's open",2,"It was open when I got here",1,"Liar",2,"Fine, I touched it a little"}},
