{"fw_ld4_quick_e_0019","any",2,"reg=civilian,family,worker,rescue",{1,"Stop looking at me like that",2,"Like what?",1,"Like I'm already gone",2,"I am sorry, I am not looking at you like that, I'm looking at you like you're staying"}},
{"fw_ld4_quick_e_0020","any",2,"reg=civilian,family,worker,rescue",{1,"Did you steal my tobacco?",2,"I borrowed it",1,"Without asking?",2,"Borrowing is just stealing with an intention to return",1,"Return it, or I'll steal your toothbrush"}},
{"fw_ld4_quick_e_0021","any",2,"reg=civilian,family,worker,rescue",{1,"Say you're sorry",2,"I'm sorry",1,"Say it like you mean it",2,"I'M SORRY",1,"Better, but too loud"}},
