{"fw_ld4_quick_e_0035","any",2,"reg=outlaw,raider,gang,club,crime,prison",{1,"You touched my bottle",2,"I didn't",1,"I can smell it on you",2,"...it was a sip, one sip"}},
{"fw_ld4_quick_e_0036","any",2,"reg=outlaw,raider,gang,club,crime,prison",{1,"Don't snitch",2,"I wouldn't",1,"Swear",2,"On my mother",1,"Your mother's dead",2,"That's why I mean it"}},
{"fw_ld4_quick_e_0037","any",2,"reg=outlaw,raider,gang,club,crime,prison",{1,"You've got blood on your sleeve",2,"It's not mine",1,"Whose?",2,"Doesn't matter, forget it"}},
{"fw_ld4_quick_e_0038","any",2,"reg=outlaw,raider,gang,club,crime,prison",{1,"Why'd you do it?",2,"Do what?",1,"Shoot the old man",2,"He looked at me funny",1,"That's it? That's your reason?",2,"It's the only one I have"}},
{"fw_ld4_quick_e_0039","any",2,"reg=family",{1,"Don't talk back",2,"But Mama",1,"No buts",2,"But-",1,"Not one more but"}},
{"fw_ld4_quick_e_0040","any",2,"reg=family",{1,"Papa, you're mad",2,"I'm not mad",1,"Your face is mad",2,"My face is tired, it looks mad, there's a difference"}},
{"fw_ld4_quick_e_0041","any",2,"reg=family",{1,"I don't want to go",2,"We have to",1,"Why?",2,"Because staying will hurt us more than going",1,"Okay, Papa"}},
{"fw_ld4_quick_f_0001","any",2,"reg=civilian,family,worker,rescue",{1,"Be honest, how bad do I smell?",2,"Like a wet dog that's been in a sock",1,"Is that bad?",2,"It's the best smell in the county, we all smell like that"}},
{"fw_ld4_quick_f_0002","any",2,"reg=civilian,family,worker,rescue",{1,"Is it me, or is everyone eyeing the last biscuit?",2,"Everyone",1,"Then we split it",2,"Into seven pieces?",1,"Into seven crumbs, we're civilized"}},
{"fw_ld4_quick_f_0003","any",2,"reg=civilian,family,worker,rescue",{1,"What's your biggest fear?",2,"Being bitten",1,"Mine's being alone",2,"Then stay close, and I'll stay unbitten"}},
{"fw_ld4_quick_f_0004","any",2,"reg=civilian,family,worker,rescue",{1,"I wish I had a camera",2,"For what?",1,"To remember this",2,"You'll never forget it, trust the brain, it's merciless"}},
{"fw_ld4_quick_f_0005","any",2,"reg=civilian,family,worker,rescue|world=hot",{1,"Lend me your jacket",2,"It's hot",1,"I'm cold",2,"You're always cold",1,"Because I'm skinny and unloved"}},
{"fw_ld4_quick_f_0006","any",2,"reg=civilian,family,worker,rescue",{1,"Say, do you believe in luck?",2,"I believe in numbers",1,"What numbers?",2,"One in eight, one in ten, one in five, they all add up to 'maybe tomorrow'"}},
{"fw_ld4_quick_f_0007","any",2,"reg=civilian,family,worker,rescue",{1,"Eat a little",2,"I'm not hungry",1,"Eat anyway",2,"You sound like my mother",1,"Then listen to her"}},
